# ------------------------------------------------------------------
# EXPERIMENT: ROS2 Multi-Robot MAPF Controller
#
# This ROS2 node implements a trajectory-following controller for executing
# MAPF paths generated by ICBS or RHCR planners. It handles navigation,
# synchronization, lifter control, and data logging for the physical robots.
# ------------------------------------------------------------------

import os
import csv
import rclpy
from rclpy.node import Node
from rclpy.qos import qos_profile_sensor_data
import math
import time
import socket
from datetime import datetime
from geometry_msgs.msg import Twist
from nav_msgs.msg import Odometry
from sensor_msgs.msg import Joy, PointCloud2
from std_msgs.msg import Bool, Int32


# Hardcoded map: robot hostname → agent ID in the trajectory file.
# EDIT HERE: assign each physical robot to one of the agents in the
# .txt path file (agents 0, 1, 2).
HOSTNAME_TO_AGENT_ID = { 
    # 'robot_89a8fd55': 0,   # r21
    # 'robot_55a4e4cc': 1,   # r22
    # 'robot_9178a1f7': 2,   # r23
    'robot_31c4efef': 1,   # r24
    'robot_b6bd40d3': 0,   # r25
    #'robot_ed59744e': 1,   # r27
    #'robot_e213b058': 2,   # r28
    'robot_68d8f877': 2,   # r29
    #'robot_c176221d': 1,   # r31
    #'robot_46df6ee3': 2,   # r32
    #'robot_406c069b': 1,   # r34
    #'robot_5d3ba8ad': 0,   # r35
    #'robot_8578302a': 0,   # r37
}

ARENA_SIZE = 3.7

# ------------------------------------------------------------------
# Loads MAPF trajectories generated by ICBS or RHCR planners.
#
# File format:
# - Each agent starts with its numeric identifier
# - Subsequent lines contain waypoint sequences
# - Each line represents one goal segment
#
# Returns:
# - Dictionary mapping agent IDs to trajectory segments
# - Each segment contains a sequence of (x, y) waypoints
#
# These trajectories are later executed by the ROS2 controller.
# ------------------------------------------------------------------

def load_trajectories(filepath):
    trajectories = {}
    current_id = None
    segments = []

    with open(filepath) as f:
        for raw in f:
            line = raw.strip()
            if not line:
                continue
            parts = line.split()
            if len(parts) == 1:
                if current_id is not None:
                    trajectories[current_id] = segments
                current_id = int(parts[0])
                segments = []
            else:
                nums = list(map(float, parts))
                points = [(nums[i], nums[i + 1]) for i in range(0, len(nums) - 1, 2)]
                segments.append(points)

    if current_id is not None:
        trajectories[current_id] = segments

    return trajectories

# ICBS barrier hold time (seconds) after all robots report goal reached
ICBS_SYNC_HOLD = 5.0

# Delay (seconds) between arriving at a goal and actuating the lifter, to allow the robot to come to rest before the load shifts up/down
LIFTER_DELAY = 1.0

# Sentinel value used when a robot has completed all assigned goals.
#
# Since ICBS synchronization uses comparisons of the form:
#     peer_seq >= sync_counter
# this large value ensures that the finished robot is always considered
# "ahead" of all others.
#
# As a result, no other robot will ever block waiting for this agent again.
ICBS_DONE_SENTINEL = 2 ** 30

# ------------------------------------------------------------------
# MAPF trajectory controller
#
# This node acts as the execution layer between the MAPF planner and
# the physical robots.
#
# It receives precomputed trajectories, converts them into arena
# coordinates and drives the robot through the assigned waypoints
# while maintaining localization, synchronization and payload control,
# including ICBS (synchronized) and RHCR (continuous execution) modes.
# ------------------------------------------------------------------

class MapfTrajectoryController(Node):

    # ------------------------------------------------------------------
    # Controller initialization
    #
    # Startup consists of four major stages:
    # 1. Load configuration parameters
    # 2. Identify which MAPF agent this robot represents
    # 3. Load and convert the assigned trajectory
    # 4. Create ROS interfaces and runtime state
    #
    # Once initialization completes, the robot remains idle until an
    # ArUco localization fix is available and the operator arms the run.
    # ------------------------------------------------------------------

    def __init__(self):
        super().__init__('mapf_trajectory_controller')

        # Defines the number of boxes used in the experiment
        self.box = 8

        # Selects which experiment scenario dataset to load
        self.example = 14

        # Defines the navigation speed (m/s)
        self.declare_parameter('speed', 0.1)

        self.declare_parameter('arrival_threshold', 0.08)

        # Number of consecutive ticks required to confirm waypoint arrival
        self.declare_parameter('arrival_count', 3)

        self.declare_parameter('joy_scale', 0.3)
        self.declare_parameter('wscale', 1.5)
        self.declare_parameter('heading_gain', 2.0)

        # Time (seconds) for EKF stabilization before starting motion
        self.declare_parameter('ekf_settle_time', 10.0)

        # Default -1 = "auto-detect from hostname via HOSTNAME_TO_AGENT_ID"
        self.declare_parameter('robot_id', -1)

        self.speed = float(self.get_parameter('speed').value)
        self.arrival_threshold = float(self.get_parameter('arrival_threshold').value)
        self.arrival_required = int(self.get_parameter('arrival_count').value)
        self.joy_scale = float(self.get_parameter('joy_scale').value)
        self.wscale = float(self.get_parameter('wscale').value)
        self.heading_gain = float(self.get_parameter('heading_gain').value)
        self.ekf_settle_time = float(self.get_parameter('ekf_settle_time').value)
        self.robot_name = socket.gethostname().replace('-', '_')
        param_robot_id = int(self.get_parameter('robot_id').value)

        if param_robot_id < 0:
            self.robot_id = HOSTNAME_TO_AGENT_ID.get(self.robot_name, 0)
            self.get_logger().info(
                f'robot_id auto-detected: {self.robot_name} → agent {self.robot_id}'
            )
        else:
            self.robot_id = param_robot_id
            self.get_logger().info(
                f'robot_id from launch arg: agent {self.robot_id}'
            )

        # Mode selection (ICBS or RHCR)
        self.mode = "ICBS"

        pkg_dir = os.path.dirname(os.path.abspath(__file__))
        self.paths_files = {
            "ICBS": os.path.join(pkg_dir, f"{self.box}_boxes", f"example{self.example}", f"example{self.example}_icbs_converted_paths.txt"),
            "RHCR": os.path.join(pkg_dir, f"{self.box}_boxes", f"example{self.example}", f"example{self.example}_rhcr_converted_paths.txt"),
        }
        traj_file = self.paths_files[self.mode]

        # Load trajectory file
        try:
            all_trajectories = load_trajectories(traj_file)
        except Exception as e:
            self.get_logger().error(f'Failed to load trajectory file "{traj_file}": {e}')
            raise

        if self.robot_id not in all_trajectories:
            self.get_logger().error(
                f'Agent ID {self.robot_id} not found in "{traj_file}". '
                f'Available IDs: {sorted(all_trajectories.keys())}'
            )
            raise RuntimeError(f'Agent ID {self.robot_id} not in trajectory file')

        # Goals: list of segments, in which each segment is a list of (x, y) waypoints.
        # The last point of each segment is the "goal" for that segment.
        self.goals = []
        for raw_segment in all_trajectories[self.robot_id]:
            segment = []
            for raw_x, raw_y in raw_segment:                
                # For real swarm arena 3.7m x 3.7m and 6x6 grid:
                x = (raw_x - 3) * (3.7/6)
                y = (raw_y - 3) * (3.7/6)

                segment.append((x, y))
                self.get_logger().info(
                    f"{self.robot_name} loaded waypoint ({x:.2f}, {y:.2f} from old ({raw_x}, {raw_y}))"
                )
            self.goals.append(segment)

        self.goal_index = 0   # which segment we are currently pursuing
        self.wp_index = 0     # which waypoint within the current segment
        self.lap_count = 0    # how many times we have completed all goals

        total_wps = sum(len(s) for s in self.goals)
        self.get_logger().info(
            f'Agent {self.robot_id}: {len(self.goals)} goals, '
            f'{total_wps} total waypoints loaded from "{traj_file}" (mode={self.mode})'
        )

        # Define arena bound
        self.arena_bound = ARENA_SIZE / 2.0

        # ------------------------------------------------------------------
        # ICBS barrier synchronization
        #
        # Each robot publishes its goal-completion counter on topic /icbs_sync/<id>.
        # A robot waits at every goal until ALL peers have also reached that
        # goal (counter >= own counter), then holds for ICBS_SYNC_HOLD seconds.
        #
        # Counter increments by 1 on every goal completion regardless of lap, so 
        # robots with different numbers of goals are still comparable, so the fast 
        # robot waits until the slow one catches up.
        #
        # In RHCR mode these topics are not created and no waiting happens.
        # ------------------------------------------------------------------

        all_agent_ids = sorted(all_trajectories.keys())

        if self.mode == "ICBS":
            self.sync_counter = 0  # goals completed by this robot
            self.peer_sync_counter = {aid: 0 for aid in all_agent_ids}
            self.waiting_sync = False      
            self.sync_done_time = None  # set when all peers are ready
            self.all_goals_done = False    
            self.goal_arrival_time = None  
            self.lifter_pending = False    
            self.pending_lifter_state = False  

            self.sync_pub = self.create_publisher(
                Int32, f'/icbs_sync_{self.robot_id}', 10)

            for aid in all_agent_ids:
                self.create_subscription(
                    Int32, f'/icbs_sync_{aid}',
                    lambda msg, aid=aid: self._sync_callback(msg, aid), 10)

        # Publishers
        self.cmd_vel_pub = self.create_publisher(Twist, 'cmd_vel', 10)
        self.lifter_pub = self.create_publisher(Bool, 'lifter', 10)

        # Subscribers
        self.joy_sub = self.create_subscription(Joy, 'joy', self.joy_callback, 10)
        self.filtered_sub = self.create_subscription(
            Odometry, 'odometry/filtered', self.filtered_callback,
            qos_profile=qos_profile_sensor_data)
        self.raw_odom_sub = self.create_subscription(
            Odometry, 'odom', self.raw_odom_callback, 10)
        self.aruco_sub = self.create_subscription(
            Odometry, 'cam_aruco_odom', self.aruco_callback,
            qos_profile=qos_profile_sensor_data)

        # Timers
        self.control_timer = self.create_timer(0.05, self.control_callback)   # 20Hz
        self.csv_timer = self.create_timer(0.1, self.csv_callback)            # 10Hz
        self.status_timer = self.create_timer(1.0, self.status_callback)      # 1Hz

        # Joystick state
        self.joy_vx = 0.0
        self.joy_vy = 0.0
        self.joy_w = 0.0

        # D-pad edge detection (speed tuning only)
        self.prev_dpad_left = False
        self.prev_dpad_right = False

        # Arming / settling
        self.armed = False
        self.settling = False
        self.settle_start = 0.0
        self.start_time = time.monotonic()
        self.ekf_diverged = False

        # Localization state
        self.filtered_x = 0.0
        self.filtered_y = 0.0
        self.filtered_yaw = 0.0
        self.held_yaw = 0.0
        self.raw_odom_x = 0.0
        self.raw_odom_y = 0.0
        self.raw_odom_yaw = 0.0
        self.aruco_x = 0.0
        self.aruco_y = 0.0
        self.aruco_yaw = 0.0
        self.aruco_time = 0.0
        self.aruco_count = 0

        # Lifter state
        # Odd goal number → UP
        # Even goal number → DOWN
        self.lifter_up = False
        self.lifter_toggle_count = 0

        # Arrival counter
        self.arrival_ticks = 0

        # Last commanded velocities (for logging)
        self.cmd_vx = 0.0
        self.cmd_vy = 0.0

        # CSV log file
        log_dir = '/workspace/logs'
        os.makedirs(log_dir, exist_ok=True)
        stamp = datetime.now().strftime('%Y%m%d_%H%M%S')
        self.csv_path = os.path.join(
            #log_dir, f'boxes_{self.box}_example_{self.example}_{self.robot_name}_{stamp}.csv'
            log_dir, f'mapf_trajectory_{self.robot_name}_{stamp}.csv'
        )
        self.csv_file = open(self.csv_path, 'w', newline='')
        self.csv_writer = csv.writer(self.csv_file)
        self.csv_writer.writerow([
            'time', 'lap_count', 'goal_index', 'wp_index', 'target_x', 'target_y',
            'filtered_x', 'filtered_y', 'filtered_yaw',
            'raw_odom_x', 'raw_odom_y', 'raw_odom_yaw',
            'aruco_x', 'aruco_y', 'aruco_yaw', 'aruco_age', 'aruco_count',
            'cmd_vx', 'cmd_vy', 'dist_to_target',
            'lifter_up', 'lifter_toggle_count',
        ])
        self.csv_rows = 0
        self.csv_file.flush()

        self.get_logger().info(
            f'mapf_trajectory: robot={self.robot_name}, agent_id={self.robot_id}, '
            f'mode={self.mode}, goals={len(self.goals)}, speed={self.speed}m/s, '
            f'settle={self.ekf_settle_time}s'
        )
        self.get_logger().info('Waiting for ArUco fix, then press O to start')

    # ------------------------------------------------------------------
    # Receives synchronization messages from peer robots.
    #
    # Each message contains the sender's current progress counter.
    # These counters are later compared during ICBS barrier checks to
    # determine whether all robots may proceed.
    # ------------------------------------------------------------------

    def _sync_callback(self, msg, agent_id):
        self.peer_sync_counter[agent_id] = msg.data

    # ------------------------------------------------------------------
    # Joystick control interface.
    #
    # The joystick serves two purposes:
    #
    # - Arm and supervise autonomous execution
    # - Apply small manual corrections during navigation
    #
    # It also allows runtime adjustment of controller speed without
    # restarting the node.
    # ------------------------------------------------------------------

    def joy_callback(self, msg):
        # Game controller O button arms, but requires at least one ArUco fix
        if not self.armed and len(msg.buttons) > 2 and msg.buttons[2]:
            if self.aruco_count < 1:
                self.get_logger().warn('Cannot arm - no ArUco fix yet')
            else:
                self.armed = True
                self.settling = True
                self.settle_start = time.monotonic()
                self.start_time = time.monotonic()
                self.held_yaw = self.filtered_yaw
                self.get_logger().info(
                    f'O pressed - heading hold={self.held_yaw:.1f}°, '
                    f'settling EKF for {self.ekf_settle_time}s...'
                )

        # Auto-detect game controller type
        if len(msg.buttons) >= 17:
            axis_w = 3       # DS3
        elif len(msg.buttons) >= 13:
            axis_w = 2       # Knockoff DS3 generic
        else:
            axis_w = 3       # Xbox 360

        # Left stick: translational nudge
        if len(msg.axes) >= 2:
            self.joy_vx = msg.axes[1] * self.joy_scale
            self.joy_vy = msg.axes[0] * self.joy_scale

        # Right stick: rotation
        if len(msg.axes) > axis_w:
            self.joy_w = msg.axes[axis_w] * self.wscale

        # D-pad: speed tuning (left/right only)
        if len(msg.buttons) >= 17:
            dpad_left = bool(msg.buttons[15])
            dpad_right = bool(msg.buttons[16])
        elif len(msg.axes) >= 8:
            dpad_left = msg.axes[6] > 0.5
            dpad_right = msg.axes[6] < -0.5
        else:
            dpad_left = dpad_right = False

        changed = False
        if dpad_right and not self.prev_dpad_right:
            self.speed = round(self.speed + 0.05, 2)
            changed = True
        if dpad_left and not self.prev_dpad_left:
            self.speed = round(max(0.05, self.speed - 0.05), 2)
            changed = True

        if changed:
            self.get_logger().info(f'D-pad: speed={self.speed}m/s')

        self.prev_dpad_left = dpad_left
        self.prev_dpad_right = dpad_right

    # ------------------------------------------------------------------
    # Controls the robot lifter mechanism.
    #
    # The lifter is toggled at goal locations to simulate pickup and
    # delivery operations. Duplicate commands are ignored to avoid
    # unnecessary actuator traffic.
    # ------------------------------------------------------------------

    def _set_lifter(self, up: bool):
        if up == self.lifter_up:
            return
        self.lifter_up = up
        self.lifter_toggle_count += 1
        msg = Bool()
        msg.data = self.lifter_up
        self.lifter_pub.publish(msg)
        state_str = 'UP' if self.lifter_up else 'DOWN'
        self.get_logger().info(
            f'Lifter → {state_str} (#{self.lifter_toggle_count})'
        )

    # Converts quaternion orientation into yaw angle (rad/deg)
    def _quat_to_yaw(self, q):
        siny_cosp = 2.0 * (q.w * q.z + q.x * q.y)
        cosy_cosp = 1.0 - 2.0 * (q.y * q.y + q.z * q.z)
        return math.atan2(siny_cosp, cosy_cosp)

    # Receives EKF filtered odometry (primary localization source)
    def filtered_callback(self, msg):
        p = msg.pose.pose
        self.filtered_x = p.position.x
        self.filtered_y = p.position.y
        self.filtered_yaw = math.degrees(self._quat_to_yaw(p.orientation))

    # Receives raw wheel odometry (unfiltered motion estimate)
    def raw_odom_callback(self, msg):
        p = msg.pose.pose
        self.raw_odom_x = p.position.x
        self.raw_odom_y = p.position.y
        self.raw_odom_yaw = math.degrees(self._quat_to_yaw(p.orientation))

    # Receives vision-based pose estimate from ArUco detection
    def aruco_callback(self, msg):
        p = msg.pose.pose
        self.aruco_x = p.position.x
        self.aruco_y = p.position.y
        self.aruco_yaw = math.degrees(self._quat_to_yaw(p.orientation))
        self.aruco_time = time.monotonic()
        self.aruco_count += 1

    # ------------------------------------------------------------------
    # Main navigation and execution loop (20 Hz).
    #
    # Responsibilities:
    # - Wait for arming and EKF stabilization
    # - Execute waypoint-following control
    # - Detect waypoint and goal arrivals
    # - Perform ICBS synchronization barriers
    # - Control lifter actions at goals
    # - Maintain heading using proportional control
    # - Publish velocity commands to the robot
    # ------------------------------------------------------------------

    def control_callback(self):
        if not self.armed:
            self.cmd_vx = 0.0
            self.cmd_vy = 0.0
            self.cmd_vel_pub.publish(Twist())
            return

        # Settling zero velocity while EKF converges
        if self.settling:
            self.cmd_vx = 0.0
            self.cmd_vy = 0.0
            self.cmd_vel_pub.publish(Twist())
            if time.monotonic() - self.settle_start >= self.ekf_settle_time:
                self.settling = False
                self.start_time = time.monotonic()
                tx, ty = self.goals[self.goal_index][self.wp_index]
                self.get_logger().info(
                    f'EKF settled - navigating! '
                    f'Goal 1/{len(self.goals)}, first waypoint: ({tx:.2f}, {ty:.2f})'
                )
            return

        # ICBS barrier: hold position until all robots reach this goal
        if self.mode == "ICBS" and self.waiting_sync:
            self.cmd_vx = 0.0
            self.cmd_vy = 0.0
            self.cmd_vel_pub.publish(Twist())

            # Lifter delay: robot has stopped at the goal, then wait for LIFTER_DELAY so 
            # the load doesn't shift while the robot is still moving
            if (self.lifter_pending and
                    time.monotonic() - self.goal_arrival_time >= LIFTER_DELAY):
                self._set_lifter(self.pending_lifter_state)
                self.lifter_pending = False

            all_ready = all(
                seq >= self.sync_counter
                for seq in self.peer_sync_counter.values()
            )

            if all_ready:
                if self.sync_done_time is None:
                    # First tick where everyone is ready, start the hold timer
                    self.sync_done_time = time.monotonic()
                    self.get_logger().info(
                        f'All robots at goal {self.goal_index + 1} - '
                        f'holding for {ICBS_SYNC_HOLD:.0f}s'
                    )
                elif time.monotonic() - self.sync_done_time >= ICBS_SYNC_HOLD:
                    # Hold complete, advance to the next goal
                    self.waiting_sync = False
                    self.sync_done_time = None

                    self.goal_index += 1
                    self.wp_index = 0

                    if self.goal_index >= len(self.goals):
                        # All goals finished, publish sentinel so peers never wait for this robot again
                        elapsed = time.monotonic() - self.start_time
                        self.all_goals_done = True
                        self.sync_counter = ICBS_DONE_SENTINEL
                        sync_msg = Int32()
                        sync_msg.data = self.sync_counter
                        self.sync_pub.publish(sync_msg)
                        self.peer_sync_counter[self.robot_id] = self.sync_counter
                        self.get_logger().info(
                            f'All goals complete ({elapsed:.0f}s) - robot is done'
                        )
                    else:
                        self.get_logger().info(
                            f'Proceeding to goal {self.goal_index + 1}/{len(self.goals)}'
                        )
            return

        # ICBS done, that is, all goals finished, hold position indefinitely
        if self.mode == "ICBS" and self.all_goals_done:
            self.cmd_vx = 0.0
            self.cmd_vy = 0.0
            self.cmd_vel_pub.publish(Twist())
            return

        # Current target
        tx, ty = self.goals[self.goal_index][self.wp_index]

        # # Clamp EKF-based position to arena bounds to prevent navigation instability
        # and avoid unsafe motion when the state estimate diverges.
        nav_x = self.filtered_x
        nav_y = self.filtered_y
        clamped = False
        if abs(nav_x) > self.arena_bound:
            nav_x = math.copysign(self.arena_bound, nav_x)
            clamped = True
        if abs(nav_y) > self.arena_bound:
            nav_y = math.copysign(self.arena_bound, nav_y)
            clamped = True
        if clamped and not self.ekf_diverged:
            self.ekf_diverged = True
            self.get_logger().warn(
                f'EKF outside arena! pos=({self.filtered_x:.2f},{self.filtered_y:.2f}) '
                f'clamped to ({nav_x:.2f},{nav_y:.2f})'
            )
        elif not clamped and self.ekf_diverged:
            self.ekf_diverged = False
            self.get_logger().info(f'EKF back in arena - pos=({nav_x:.2f},{nav_y:.2f})')

        # Direction vector from nav position to waypoint
        dx = tx - nav_x
        dy = ty - nav_y
        dist = math.sqrt(dx * dx + dy * dy)

        # Arrive when within threshold for N consecutive control ticks
        if dist < self.arrival_threshold:
            self.arrival_ticks += 1
        else:
            self.arrival_ticks = 0

        if self.arrival_ticks >= self.arrival_required:
            self.arrival_ticks = 0
            current_segment = self.goals[self.goal_index]

            if self.wp_index < len(current_segment) - 1:
                # Intermediate waypoint within the segment - just advance
                self.wp_index += 1
                self.get_logger().info(
                    f'Waypoint {self.wp_index + 1}/{len(current_segment)} '
                    f'in goal {self.goal_index + 1}'
                )

            else:
                # Last waypoint = goal reached
                goal_number = self.goal_index + 1
                lifter_target = (goal_number % 2 == 1)   # odd → UP, even → DOWN
                elapsed = time.monotonic() - self.start_time

                if self.mode == "ICBS":
                    # Signal all peers and enter the barrier wait state.
                    # goal_index is not advanced yet, that happens after sync.
                    self.sync_counter += 1
                    sync_msg = Int32()
                    sync_msg.data = self.sync_counter
                    self.sync_pub.publish(sync_msg)

                    # Velocity zero while waiting for peers to catch up
                    self.cmd_vx = 0.0
                    self.cmd_vy = 0.0
                    self.cmd_vel_pub.publish(Twist())

                    # Update own entry directly so we don't wait for ourselves
                    self.peer_sync_counter[self.robot_id] = self.sync_counter
                    self.waiting_sync = True
                    self.sync_done_time = None
                    # Arm the deferred lifter actuation, actual toggle happens
                    # LIFTER_DELAY seconds later inside the barrier wait
                    self.goal_arrival_time = time.monotonic()
                    self.pending_lifter_state = lifter_target
                    self.lifter_pending = True
                    self.get_logger().info(
                        f'Goal {goal_number} reached ({elapsed:.0f}s) - '
                        f'waiting for all robots (sync={self.sync_counter})'
                    )
                    # Return immediately; the barrier block handles everything next tick
                    return

                else:
                    # RHCR: actuate lifter immediately and advance, no waiting
                    self._set_lifter(lifter_target)
                    self.goal_index += 1
                    self.wp_index = 0

                    if self.goal_index >= len(self.goals):
                        self.goal_index = 0
                        self.lap_count += 1
                        self.get_logger().info(
                            f'All goals complete - lap {self.lap_count} ({elapsed:.0f}s), '
                            f'restarting from goal 1'
                        )
                    else:
                        self.get_logger().info(
                            f'Goal {goal_number} reached ({elapsed:.0f}s) - '
                            f'proceeding to goal {self.goal_index + 1}/{len(self.goals)}'
                        )

            # Recompute for new target
            tx, ty = self.goals[self.goal_index][self.wp_index]
            dx = tx - nav_x
            dy = ty - nav_y
            dist = math.sqrt(dx * dx + dy * dy)

        # Pure proportional control: velocity proportional to target error, with speed saturation
        gain = 0.8
        effective_speed = min(self.speed, gain * dist)

        if dist > 0.001:
            vx = (dx / dist) * effective_speed
            vy = (dy / dist) * effective_speed
        else:
            vx = 0.0
            vy = 0.0

        # Rotate world-frame velocity into robot body frame using held heading
        yaw_rad = math.radians(self.held_yaw)
        cos_yaw = math.cos(yaw_rad)
        sin_yaw = math.sin(yaw_rad)
        body_vx =  cos_yaw * vx + sin_yaw * vy
        body_vy = -sin_yaw * vx + cos_yaw * vy

        # Joystick nudge (already in body frame)
        body_vx += self.joy_vx
        body_vy += self.joy_vy

        # Heading hold: P-controller to maintain armed heading
        yaw_err = self.held_yaw - self.filtered_yaw
        yaw_err = (yaw_err + 180.0) % 360.0 - 180.0
        heading_w = self.heading_gain * math.radians(yaw_err)

        self.cmd_vx = body_vx
        self.cmd_vy = body_vy

        msg = Twist()
        msg.linear.x = body_vx
        msg.linear.y = body_vy
        msg.angular.z = heading_w + self.joy_w
        self.cmd_vel_pub.publish(msg)

    # ------------------------------------------------------------------
    # Experiment data logger
    #
    # Periodically records navigation, localization and lifter state
    # information to a CSV file.
    #
    # These logs are later consumed by analysis scripts to reconstruct
    # trajectories, evaluate localization quality and compare planner
    # performance.
    # ------------------------------------------------------------------

    def csv_callback(self):
        now = time.monotonic()
        aruco_age = now - self.aruco_time if self.aruco_time > 0 else -1.0

        tx, ty = self.goals[self.goal_index][self.wp_index]
        dx = tx - self.filtered_x
        dy = ty - self.filtered_y
        dist = math.sqrt(dx * dx + dy * dy)

        self.csv_writer.writerow([
            f'{now - self.start_time:.3f}', self.lap_count,
            self.goal_index, self.wp_index,
            f'{tx:.4f}', f'{ty:.4f}',
            f'{self.filtered_x:.4f}', f'{self.filtered_y:.4f}', f'{self.filtered_yaw:.4f}',
            f'{self.raw_odom_x:.4f}', f'{self.raw_odom_y:.4f}', f'{self.raw_odom_yaw:.4f}',
            f'{self.aruco_x:.4f}', f'{self.aruco_y:.4f}', f'{self.aruco_yaw:.4f}',
            f'{aruco_age:.3f}', self.aruco_count,
            f'{self.cmd_vx:.4f}', f'{self.cmd_vy:.4f}', f'{dist:.4f}',
            int(self.lifter_up), self.lifter_toggle_count,
        ])
        self.csv_rows += 1
        if self.csv_rows % 100 == 0:
            self.csv_file.flush()

    # ------------------------------------------------------------------
    # Prints runtime status information to the console.
    #
    # Produces human-readable summaries of the controller state at 1 Hz.
    # The output is intended for operators during experiments and helps
    # diagnose localization issues, synchronization delays and navigation
    # progress without inspecting raw ROS topics.
    # ------------------------------------------------------------------

    def status_callback(self):
        if not self.armed:
            aruco_age = time.monotonic() - self.aruco_time if self.aruco_time > 0 else -1.0
            self.get_logger().info(
                f'ekf=({self.filtered_x:.2f},{self.filtered_y:.2f}) '
                f'raw=({self.raw_odom_x:.2f},{self.raw_odom_y:.2f}) '
                f'aruco=({self.aruco_x:.2f},{self.aruco_y:.2f}) '
                f'n={self.aruco_count} age={aruco_age:.1f}s '
                f'{"- press O" if self.aruco_count > 0 else "waiting..."}'
            )
            return

        if self.settling:
            remaining = self.ekf_settle_time - (time.monotonic() - self.settle_start)
            self.get_logger().info(f'EKF settling... {remaining:.1f}s remaining')
            return

        # ICBS barrier wait status
        if self.mode == "ICBS" and self.waiting_sync:
            waiting_for = [
                aid for aid, seq in self.peer_sync_counter.items()
                if seq < self.sync_counter
            ]
            if waiting_for:
                self.get_logger().info(
                    f'[ICBS] Goal {self.goal_index + 1} reached - '
                    f'waiting for robots: {waiting_for}'
                )
            else:
                remaining = ICBS_SYNC_HOLD - (time.monotonic() - self.sync_done_time)
                self.get_logger().info(
                    f'[ICBS] All robots synchronized - '
                    f'{remaining:.1f}s until goal {self.goal_index + 2}'
                )
            return

        elapsed = time.monotonic() - self.start_time
        aruco_age = time.monotonic() - self.aruco_time if self.aruco_time > 0 else -1.0
        tx, ty = self.goals[self.goal_index][self.wp_index]
        dx = tx - self.filtered_x
        dy = ty - self.filtered_y
        dist = math.sqrt(dx * dx + dy * dy)
        segment = self.goals[self.goal_index]
        lifter_str = 'UP' if self.lifter_up else 'DN'

        self.get_logger().info(
            f'[{elapsed:.0f}s] lap={self.lap_count} '
            f'goal={self.goal_index + 1}/{len(self.goals)} '
            f'wp={self.wp_index + 1}/{len(segment)} '
            f'pos=({self.filtered_x:.2f},{self.filtered_y:.2f}) '
            f'→({tx:.2f},{ty:.2f}) d={dist:.3f}m '
            f'aruco_n={self.aruco_count} age={aruco_age:.1f}s '
            f'lifter={lifter_str}({self.lifter_toggle_count})'
        )

# ------------------------------------------------------------------
# ROS2 application entry point.
#
# Creates a single trajectory controller instance and hands control
# over to the ROS executor. From this point onward all behaviour is
# event-driven through ROS callbacks and timers.
# ------------------------------------------------------------------

def main():
    rclpy.init()
    controller = MapfTrajectoryController()
    rclpy.spin(controller)

if __name__ == '__main__':
    main()